select * from ai_memory
 where memory_id = #{memoryId}
   and user_id = #{userId}
   and agent_id = #{agentId}
   and del_flag = '0'

select * from ai_memory
 where user_id = #{userId}
   and memory_id in

    #{id}

   and del_flag = '0'

select * from ai_memory
 where user_id = #{userId}
   and del_flag = '0'

select * from ai_memory

    del_flag = '0'
    and user_id = #{userId}
    and agent_id = #{agentId}
    and type = #{type}
    and status = #{status}
    and content like concat('%', #{content}, '%')

order by create_time desc, memory_id desc

select * from ai_memory
 where user_id = #{userId}
   and agent_id = #{agentId}
   and content_hash = #{contentHash}
   and status = 'active'
   and del_flag = '0'
 limit 1

select count(*) from ai_memory
 where user_id = #{userId}
   and agent_id = #{agentId}
   and status = 'active'
   and del_flag = '0'

