update ai_memory
   set status = 'superseded',
       superseded_by = #{supersededBy},
       update_time = now()
 where memory_id = #{memoryId}
   and user_id = #{userId}
   and agent_id = #{agentId}
   and status = 'active'
   and del_flag = '0'
